input.function:
async () => {
  // 1) Confirma que o base.css servido contém a regra nova
  const link = [...document.querySelectorAll('link[rel=stylesheet]')].find(l => /css\/base\.css/.test(l.href));
  let cssHasRule = false, baseHref = link ? link.href : '(não encontrado)';
  if (link) {
    try {
      const txt = await (await fetch(link.href)).text();
      cssHasRule = /font-synthesis:\s*style/.test(txt) && /entry-content/.test(txt);
    } catch(e) { cssHasRule = 'fetch falhou: '+e.message; }
  }

  // 2) Monta demo DENTRO de um container real .entry-content (onde a regra ancora)
  const prev = document.getElementById('bit-italic-demo'); if (prev) prev.remove();
  const panel = document.createElement('div');
  panel.id = 'bit-italic-demo';
  panel.className = 'entry-content'; // <- container real que a regra cobre
  panel.style.cssText = [
    'position:relative','z-index:999999','background:#1d1f21','color:#f5f5f0',
    'padding:20px 28px',
    'font-family:var(--e-global-typography-text-font-family,"Just Sans"),sans-serif',
    'font-size:18px','line-height:1.6'
  ].join(';');
  panel.innerHTML = `
    <div style="font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#7fd17f;margin-bottom:14px">
      DEPOIS do fix — dentro de .entry-content (Just Sans)
    </div>
    <div style="display:grid;grid-template-columns:200px 1fr;gap:6px 18px;align-items:baseline">
      <div style="color:#9aa">Just Sans normal:</div>
      <div class="d-normal">Em 2025, o estudo SINISA revelou dados sobre saneamento.</div>
      <div style="color:#9aa">Just Sans &lt;em&gt;:</div>
      <div><em class="d-em">Em 2025, o estudo SINISA revelou dados sobre saneamento.</em></div>
      <div style="color:#9aa">Just Sans &lt;strong&gt;&lt;em&gt;:</div>
      <div><strong><em class="d-bi">Em 2025, o estudo SINISA revelou dados.</em></strong></div>
      <div style="grid-column:1/-1;height:1px;background:#444;margin:8px 0"></div>
      <div style="color:#9aa">Ênfase .bit-emphasis-serif:</div>
      <div class="d-serif bit-emphasis-serif">Ranking do Saneamento 2025</div>
    </div>
    <div id="ro" style="margin-top:16px;font-family:monospace;font-size:13px;color:#7fd17f;white-space:pre"></div>`;
  document.body.prepend(panel);

  const read = (sel) => { const el = panel.querySelector(sel); const cs = getComputedStyle(el);
    return { fontStyle: cs.fontStyle, synth: (cs.fontSynthesisStyle||cs.fontSynthesis||'?'), fam: cs.fontFamily.split(',')[0].replace(/["']/g,'') }; };
  const em = read('.d-em'), bi = read('.d-bi'), sf = read('.d-serif');

  panel.querySelector('#ro').textContent =
    `base.css servido tem a regra? -> ${cssHasRule}\n`+
    `Just Sans <em>         -> font-style:${em.fontStyle} | font-synthesis-style:${em.synth} | font:${em.fam}\n`+
    `Just Sans <strong><em> -> font-style:${bi.fontStyle} | font-synthesis-style:${bi.synth} | font:${bi.fam}\n`+
    `.bit-emphasis-serif    -> font-style:${sf.fontStyle} | font:${sf.fam}`;

  return { baseHref, cssHasRule, em, bi, sf };
}

