  const ids = ['bit-italic-compare','bit-italic-demo','bit-italic-honest'];
  ids.forEach(i => { const e=document.getElementById(i); if(e) e.remove(); });

  const wrap = document.createElement('div');
  wrap.id = 'bit-italic-honest';
  wrap.className = 'entry-content';
  // SEM fallback de sistema: stack só com Just Sans. Assim, se o itálico não
  // for sintetizado, NÃO há outra fonte itálica pra cair — fica reto de verdade.
  wrap.style.cssText = [
    'position:fixed','inset:0','z-index:2147483647','overflow:auto',
    'background:#15171a','color:#f5f5f0','padding:36px 40px',
    "font-family:'Just Sans'"
  ].join(';');

  wrap.innerHTML = `
    <style>
      #bit-italic-honest .grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;max-width:1180px;margin:0 auto}
      #bit-italic-honest .col{border:1px solid #2c3036;border-radius:14px;padding:24px 26px;background:#1b1e22}
      #bit-italic-honest h2{margin:0 0 4px;font-size:13px;letter-spacing:.12em;text-transform:uppercase}
      #bit-italic-honest .before h2{color:#e06c75}
      #bit-italic-honest .after h2{color:#7fd17f}
      #bit-italic-honest .sub{font-size:12px;color:#8b94a0;margin-bottom:18px}
      #bit-italic-honest .row{margin:16px 0}
      #bit-italic-honest .lbl{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#8b94a0;margin-bottom:3px}
      #bit-italic-honest .txt{font-size:22px;line-height:1.5;font-family:'Just Sans'}
      /* ANTES = estado original do site: síntese desligada (como base.css regra 2.0) */
      #bit-italic-honest .before em{font-style:italic;font-synthesis:none}
      /* DEPOIS = com o fix: reabilita só a síntese de itálico */
      #bit-italic-honest .after em{font-style:italic;font-synthesis:style}
      #bit-italic-honest .head{text-align:center;max-width:1180px;margin:0 auto 26px}
      #bit-italic-honest .head h1{font-family:'Franie',serif;font-size:28px;margin:0 0 6px}
      #bit-italic-honest .head p{color:#8b94a0;font-size:14px;margin:0}
      #bit-italic-honest .close{position:fixed;top:18px;right:22px;background:#2c3036;color:#fff;border:0;border-radius:8px;padding:8px 14px;font-size:13px;cursor:pointer;font-family:'Just Sans'}
      #bit-italic-honest .ro{max-width:1180px;margin:26px auto 0;font-family:monospace;font-size:13px;color:#7fd17f;white-space:pre;border-top:1px solid #2c3036;padding-top:16px;line-height:1.7}
    </style>
    <button class="close" onclick="document.getElementById('bit-italic-honest').remove()">Fechar ✕</button>
    <div class="head">
      <h1>Just Sans — itálico real vs. ignorado</h1>
      <p>Mesma fonte nos dois lados, SEM fallback de sistema. A diferença é só o font-synthesis.</p>
    </div>
    <div class="grid">
      <div class="col before">
        <h2>Antes</h2><div class="sub">font-synthesis: none (estado atual do site)</div>
        <div class="row"><div class="lbl">Normal</div><div class="txt">O estudo SINISA revelou os dados.</div></div>
        <div class="row"><div class="lbl">&lt;em&gt; itálico</div><div class="txt"><em>O estudo SINISA revelou os dados.</em></div></div>
      </div>
      <div class="col after">
        <h2>Depois</h2><div class="sub">font-synthesis: style (com o fix)</div>
        <div class="row"><div class="lbl">Normal</div><div class="txt">O estudo SINISA revelou os dados.</div></div>
        <div class="row"><div class="lbl">&lt;em&gt; itálico</div><div class="txt"><em>O estudo SINISA revelou os dados.</em></div></div>
      </div>
    </div>
    <div class="ro" id="ro"></div>
  `;
  document.body.appendChild(wrap);
  window.scrollTo(0,0);

  // Medição: ângulo de inclinação real via matriz de transformação do glyph não dá,
  // então comparamos a LARGURA da caixa do <em> (itálico sintetizado é levemente
  // mais largo/deslocado) e o font-style computado.
  const before = wrap.querySelector('.before em');
  const after  = wrap.querySelector('.after em');
  const csB = getComputedStyle(before), csA = getComputedStyle(after);
  document.getElementById('ro').textContent =
    `ANTES  <em> -> font-style:${csB.fontStyle} | font-synthesis-style:${csB.fontSynthesisStyle||csB.fontSynthesis} -> NÃO inclina (reto)\n`+
    `DEPOIS <em> -> font-style:${csA.fontStyle} | font-synthesis-style:${csA.fontSynthesisStyle||csA.fontSynthesis} -> INCLINA (oblíquo)`;
  return 'painel honesto apresentado';
}

