async () => {
  // 1) A Just Sans REAL está carregada nesta página?
  await document.fonts.ready;
  const loaded = {
    justsans_400: document.fonts.check("400 16px 'Just Sans'"),
    justsans_800: document.fonts.check("800 16px 'Just Sans'"),
    franie_italic: document.fonts.check("italic 16px 'Franie'"),
  };

  // 2) Mede inclinação física via canvas, renderizando a MESMA Just Sans real:
  //    desenha um glifo alto ('N') e mede o deslocamento horizontal entre as
  //    linhas de pixel do topo e da base. Reto ~0px; oblíquo > vários px.
  function slantOf(fontStyleCss) {
    const c = document.createElement('canvas'); c.width=200; c.height=160;
    const ctx = c.getContext('2d');
    ctx.fillStyle='#000'; ctx.textBaseline='alphabetic';
    ctx.font = `${fontStyleCss} 120px 'Just Sans'`;
    ctx.clearRect(0,0,200,160);
    ctx.fillText('H', 30, 130);
    const img = ctx.getImageData(0,0,200,160).data;
    const rowFirstInk = (y) => { for(let x=0;x<200;x++){ if(img[(y*200+x)*4+3]>40) return x; } return -1; };
    const top = rowFirstInk(35), bot = rowFirstInk(120);   // topo vs base do glifo
    return (top>=0 && bot>=0) ? (bot - top) : null;         // >0 = inclinado p/ direita
  }

  const slantNormal = slantOf('normal');
  const slantItalic = slantOf('italic');   // com font-synthesis padrão do canvas (sintetiza)

  return {
    loaded,
    slant_normal_px: slantNormal,
    slant_italic_px: slantItalic,
    diff_px: (slantItalic!=null && slantNormal!=null) ? (slantItalic - slantNormal) : null,
    interpretacao: 'diff_px alto (>10) = itálico realmente inclina a Just Sans'
  };
}

