async () => {
  await document.fonts.ready;

  // Mede inclinação da Just Sans REAL via canvas, varrendo o glifo inteiro.
  // Para cada linha (y), acha o 1º pixel com tinta. A inclinação é a diferença
  // do x-inicial entre uma linha de cima e uma de baixo do corpo do glifo.
  function slant(fontStyleCss) {
    const W=300,H=200; const c=document.createElement('canvas'); c.width=W;c.height=H;
    const ctx=c.getContext('2d');
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle='#000'; ctx.textBaseline='alphabetic';
    ctx.font=`${fontStyleCss} 140px 'Just Sans'`;
    ctx.fillText('N', 60, 160);
    const d=ctx.getImageData(0,0,W,H).data;
    const firstInk=(y)=>{ for(let x=0;x<W;x++){ if(d[(y*W+x)*4+3]>40) return x; } return null; };
    // amostra várias linhas e acha a faixa com tinta
    let ys=[]; for(let y=30;y<175;y++){ if(firstInk(y)!=null) ys.push(y); }
    if(ys.length<10) return {ok:false};
    const yTop=ys[2], yBot=ys[ys.length-3];
    const xTop=firstInk(yTop), xBot=firstInk(yBot);
    const dyPx = yBot - yTop;
    const dxPx = xTop - xBot;               // itálico p/ direita: topo mais à direita que base
    const angleDeg = Math.atan2(dxPx, dyPx) * 180/Math.PI;
    return {ok:true, yTop, yBot, xTop, xBot, dxPx, angleDeg: +angleDeg.toFixed(1)};
  }

  const normal = slant('normal');
  const italic = slant('italic');
  return {
    justsans_loaded: document.fonts.check("400 16px 'Just Sans'"),
    normal, italic,
    delta_angle_deg: (normal.ok && italic.ok) ? +(italic.angleDeg - normal.angleDeg).toFixed(1) : null,
    veredito: (normal.ok && italic.ok)
      ? (Math.abs(italic.angleDeg - normal.angleDeg) > 6
          ? '✓ A Just Sans REAL inclina sob font-style:italic (oblíquo sintético funciona)'
          : '✗ Não houve inclinação significativa')
      : 'medição inconclusiva'
  };
}

