async () => {
  await document.fonts.ready;

  // Simula os 2 modos do Elementor e mede se font-synthesis permite inclinar.
  // Caso A: <em> dentro de widget text-editor (botão itálico do editor)
  // Caso B: Typography Style:Italic aplicado via seletor de elemento Elementor
  //         (Elementor escreve em .elementor-element-XXX, NÃO em em/i)

  const probe = document.createElement('div');
  probe.style.cssText = 'position:absolute;left:-9999px;top:0;font-family:"Just Sans",sans-serif';
  probe.innerHTML = `
    <div class="elementor-widget-text-editor"><div class="elementor-widget-container">
      <p>texto <em class="caseA">enfase editor</em></p>
    </div></div>
    <div class="elementor-element elementor-widget elementor-widget-heading caseB-wrap">
      <div class="elementor-widget-container">
        <h2 class="elementor-heading-title caseB">Titulo italico via Typography</h2>
      </div>
    </div>
    <div class="elementor-widget-button caseC-wrap">
      <div class="elementor-widget-container"><a class="elementor-button"><span class="elementor-button-text caseC">Botao italico</span></a></div>
    </div>
  `;
  document.body.appendChild(probe);

  // Caso B e C: Elementor aplicaria font-style:italic via CSS do elemento.
  // Simulo isso setando inline (equivale ao que o kit gera no seletor do elemento).
  probe.querySelector('.caseB').style.fontStyle = 'italic';
  probe.querySelector('.caseC').style.fontStyle = 'italic';
  // mas NÃO seto font-synthesis — quero ver o que o base.css resolve para cada um

  const read = (sel) => {
    const el = probe.querySelector(sel);
    const cs = getComputedStyle(el);
    return {
      fontStyle: cs.fontStyle,
      synthStyle: cs.fontSynthesisStyle || cs.fontSynthesis || '?',
      willSlant: (cs.fontStyle === 'italic' && (cs.fontSynthesisStyle === 'auto' || /style/.test(cs.fontSynthesis||'') || cs.fontSynthesis === undefined))
    };
  };

  const r = {
    A_editor_em: read('.caseA'),
    B_heading_typography: read('.caseB'),
    C_button_typography: read('.caseC'),
  };
  probe.remove();
  return r;
}

