async () => {
  await document.fonts.ready;

  // 1) Confirma regra nova no base.css servido
  const link = [...document.querySelectorAll('link[rel=stylesheet]')].find(l=>/css\/base\.css/.test(l.href));
  let ruleOk=false; try{ const t=await (await fetch(link.href)).text(); ruleOk = /\.elementor-widget-container\s*\*/.test(t) && /font-synthesis:\s*style/.test(t); }catch(e){ruleOk='err';}

  // 2) Reproduz os 3 modos do Elementor DENTRO de containers reais
  const probe=document.createElement('div');
  probe.style.cssText='position:absolute;left:-9999px;top:0;font-family:var(--e-global-typography-text-font-family,"Just Sans"),sans-serif';
  probe.innerHTML=`
    <div class="elementor-widget elementor-widget-text-editor"><div class="elementor-widget-container">
      <p>x <em class="A">enfase editor</em></p></div></div>
    <div class="elementor-widget elementor-widget-heading"><div class="elementor-widget-container">
      <h2 class="B elementor-heading-title">heading typography italic</h2></div></div>
    <div class="elementor-widget elementor-widget-button"><div class="elementor-widget-container">
      <a class="elementor-button"><span class="C elementor-button-text">botao italic</span></a></div></div>
    <div class="elementor-widget elementor-widget-heading"><div class="elementor-widget-container">
      <h2 class="D elementor-heading-title" style="font-family:'Franie',serif">Franie bold</h2></div></div>`;
  document.body.appendChild(probe);
  // Elementor aplicaria via seletor do elemento — simulo no inline style:
  probe.querySelector('.B').style.fontStyle='italic';
  probe.querySelector('.C').style.fontStyle='italic';
  probe.querySelector('.D').style.fontWeight='700'; // Franie tem 700 real → não deve sintetizar

  // medição de inclinação real por canvas, reaproveitando a fonte computada do elemento
  function slantFor(el){
    const cs=getComputedStyle(el);
    const W=320,H=200,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');
    x.clearRect(0,0,W,H);x.fillStyle='#000';x.textBaseline='alphabetic';
    x.font=`${cs.fontStyle} ${cs.fontWeight} 130px ${cs.fontFamily}`;
    x.fillText('N',70,165);
    const d=x.getImageData(0,0,W,H).data;
    const fi=(y)=>{for(let xx=0;xx<W;xx++){if(d[(y*W+xx)*4+3]>40)return xx;}return null;};
    let ys=[];for(let y=40;y<180;y++){if(fi(y)!=null)ys.push(y);}
    if(ys.length<8)return null;
    const t=ys[2],b=ys[ys.length-3];
    return +(Math.atan2(fi(t)-fi(b), b-t)*180/Math.PI).toFixed(1);
  }
  const out={
    base_css_regra_ampla: ruleOk,
    A_editor_em_deg: slantFor(probe.querySelector('.A')),
    B_heading_typography_deg: slantFor(probe.querySelector('.B')),
    C_button_typography_deg: slantFor(probe.querySelector('.C')),
    D_franie_bold_synthStyle: (getComputedStyle(probe.querySelector('.D')).fontSynthesisWeight||getComputedStyle(probe.querySelector('.D')).fontSynthesis||'?'),
  };
  probe.remove();
  out.veredito = (out.A_editor_em_deg>6 && out.B_heading_typography_deg>6 && out.C_button_typography_deg>6)
    ? '✓ Itálico do PAINEL Elementor (B,C) e do EDITOR (A) agora inclinam'
    : '✗ ainda há caso sem inclinar';
  return out;
}

