async () => {
  await document.fonts.ready;
  // Acha os parágrafos pelo texto inicial
  const needles = ['Nova publicação', 'Publicação também alerta'];
  const all = [...document.querySelectorAll('p, .elementor-widget-text-editor, .elementor-heading-title, span, div')];
  const results = [];
  for (const needle of needles) {
    // pega o elemento de texto mais específico que contém o trecho
    const cand = all.filter(el => el.textContent.trim().startsWith(needle) && el.children.length <= 3);
    const el = cand.sort((a,b)=>a.textContent.length-b.textContent.length)[0];
    if (!el) { results.push({needle, found:false}); continue; }
    const cs = getComputedStyle(el);
    // sobe a árvore pra achar o widget Elementor e como o italic foi setado
    let widget = el.closest('.elementor-widget');
    let widgetClass = widget ? [...widget.classList].filter(c=>/widget/.test(c)).join(' ') : '(nenhum)';
    let widgetId = widget ? widget.getAttribute('data-id') : null;
    // verifica de onde vem o font-style: inline? em/i? regra do elemento?
    const hasEm = !!el.querySelector('em, i') || el.tagName==='EM' || el.tagName==='I';
    const inlineFS = el.style.fontStyle || '(não inline)';
    results.push({
      needle, found:true,
      tag: el.tagName,
      outerStart: el.outerHTML.slice(0,160),
      computed_fontStyle: cs.fontStyle,
      computed_fontFamily: cs.fontFamily.split(',')[0].replace(/["']/g,''),
      computed_fontSynthesis: cs.fontSynthesis,
      computed_fontSynthesisStyle: cs.fontSynthesisStyle,
      tem_em_ou_i: hasEm,
      inline_fontStyle: inlineFS,
      widgetClass, widgetId,
      dentro_de_widget_container: !!el.closest('.elementor-widget-container'),
    });
  }
  return results;
}

async () => {
  await document.fonts.ready;

  // 1) O base.css servido NESTA página tem a regra ampla?
  const link = [...document.querySelectorAll('link[rel=stylesheet]')].find(l=>/css\/base\.css/.test(l.href));
  let cssText='', ruleAmpla=false, ruleVer=link?link.href:'(sem link)';
  if(link){ try{ cssText=await (await fetch(link.href)).text(); }catch(e){ cssText='ERR:'+e.message; } }
  ruleAmpla = /\.elementor-widget-container\s*\*/.test(cssText);

  // 2) Mede o <em> interno do 1º parágrafo (é nele que está o italic)
  const p = [...document.querySelectorAll('.elementor-widget-text-editor p')].find(el=>el.textContent.trim().startsWith('Nova publicação'));
  let emInfo=null;
  if(p){
    const em = p.querySelector('em') || p;
    const cs = getComputedStyle(em);
    // qual regra venceu o font-synthesis? lista as que aplicam
    emInfo = {
      tag: em.tagName,
      fontStyle: cs.fontStyle,
      fontFamily: cs.fontFamily.split(',')[0].replace(/["']/g,''),
      fontSynthesis: cs.fontSynthesis,
      fontSynthesisStyle: cs.fontSynthesisStyle,
      closest_widget_container: !!em.closest('.elementor-widget-container'),
      closest_entry_content: !!em.closest('.entry-content'),
      // sobe a cadeia de ancestrais com classe, pra ver a estrutura real
      ancestors: (()=>{ let a=[],n=em; while(n && n!==document.body){ if(n.className && typeof n.className==='string') a.push(n.tagName+'.'+n.className.split(/\s+/).slice(0,2).join('.')); n=n.parentElement;} return a.slice(0,8); })(),
    };
  }
  return { base_css_href: ruleVer, regra_ampla_no_css: ruleAmpla, css_len: cssText.length, em: emInfo };
}

