/*
 * base.css — Estilos globais e componentes base do tema
 * Extraído de: style.css
 * Tema: hello-elementor-child
 */

/* ==========================================================================
   2. ESTILOS GLOBAIS
   ========================================================================== */

/* --- 2.0 Proibir síntese de pesos/itálicos (fake-bold / fake-italic) ---
 * Just Sans só tem fonts reais para 400 e 800. Franie só para 400/700.
 * Sem essa regra, o browser sintetiza algoritmicamente pesos como 300, 500,
 * 600, 700 (Just Sans) ou 900 (Just Sans) — degrada legibilidade e quebra a
 * identidade tipográfica oficial (Manual de Marca §3.9). Com font-synthesis:none,
 * o browser cai no peso real mais próximo. Widgets Elementor que solicitam
 * pesos inexistentes precisam ser ajustados para valores reais (400/700/800).
 */
* {
    font-synthesis: none;
}

/* --- 2.0.1 Itálico (oblíquo sintético) só de itálico, nunca peso ---
 * A Just Sans NÃO tem itálico desenhado pela fundição (Just Creative oferece
 * 8 estilos, todos verticais). Como a regra 2.0 acima desliga font-synthesis,
 * `font-style: italic` era silenciosamente ignorado (texto saía reto) — tanto
 * no conteúdo (botão itálico do editor → <em>/<i>) quanto no painel de
 * tipografia do Elementor (Typography → Style: Italic em qualquer widget).
 *
 * Reabilitamos APENAS a síntese de itálico (`style`, NUNCA `weight`). Assim:
 *   - Just Sans em itálico → browser inclina (~13°) os pesos reais 400 e 800,
 *     funcionando para AMBOS os caminhos do Elementor (conteúdo e painel);
 *   - fake-bold continua proibido (não habilitamos `weight` → a proteção
 *     original da regra 2.0 contra pesos sintéticos permanece intacta);
 *   - Franie/Roboto seguem usando seus arquivos reais quando existem; a síntese
 *     de itálico só age como fallback quando NÃO há face itálica real, então
 *     não degrada quem já tem itálico desenhado (Franie Italic/BoldItalic).
 *
 * Cobertura: qualquer widget Elementor (`.elementor-widget-container`) e o
 * conteúdo do corpo (`.entry-content`) — pega tanto o <em>/<i> do editor
 * quanto o font-style:italic que o Elementor injeta no seletor do elemento.
 * Para itálico VERDADEIRO em ênfases editoriais escolhidas a dedo, usar a
 * classe .bit-emphasis-serif (Franie) — ver seção 2.2.
 */
.elementor-widget-container,
.elementor-widget-container *,
.entry-content,
.entry-content * {
    font-synthesis: style;
}

/* --- 2.1 HTML & Body --- */
html {
    font-size         : 16px;
    scrollbar-gutter  : stable;
    scroll-behavior   : smooth;
    scrollbar-color   : var(--e-global-color-bbe749d, #C02975) var(--e-global-color-e03d05f, #DEDDD1);
    scrollbar-width   : thin;
}

@media (prefers-reduced-motion: no-preference) {
    :has(:target) {
        scroll-behavior   : smooth;
        scroll-padding-top: 3rem;
    }
}

html body.elementor-default {
    background-color: var(--ucpa-color-offwhite);
    overflow-x      : hidden;
    position        : relative;
}

@media (max-width: 768px) {
    html, body {
        overflow-x: hidden;
    }
}

html body.elementor-kit-2553.elementor-page-26826 {
    background-color: var(--ucpa-color-offwhite);
}

/* --- 2.2 Tipografia --- */
h1, h2, h3, h4, h5, h6 {
    text-wrap: balance;
}

#content .tituloPagina {
    margin-top: 5rem;
}

/* Ênfase editorial em itálico VERDADEIRO (Franie Italic, cursivo desenhado).
 * Uso opt-in por classe num widget/trecho específico (citações de obras,
 * epígrafes) onde o oblíquo sintético da Just Sans não basta. Não afeta o
 * corpo geral. Franie tem arquivos Italic/BoldItalic reais → font-synthesis
 * herdado (none) é irrelevante aqui. */
.bit-emphasis-serif,
.bit-emphasis-serif em,
.bit-emphasis-serif i {
    font-family: 'Franie', serif;
    font-style : italic;
}

figcaption {
    text-align: center;
    color     : var(--e-global-color-text);
}

/* --- 2.3 Links --- */
html body a[href*="mailto"]:hover {
    color: currentColor;
}

.elementor-kit-2553 a:hover {
    color: var(--e-global-color-text);
}

/* Widget Bureau SVG: preserva cor no hover para não afetar fill:currentColor */
.elementor-widget-bureau_svg a:hover {
    color: inherit !important;
}

/* --- 2.4 Seleção de Texto ---
 * Texto deve permanecer SELECIONÁVEL e legível em qualquer página.
 * Fundo  = cor de destaque (Accent global), 100% dinâmico.
 * Texto  = preto OU branco, escolhido AUTOMATICAMENTE pela própria lightness
 *          do destaque, sem hardcode e sem fallback de cor. Tudo deriva de
 *          var(--e-global-color-accent) via OKLCH relative color.
 *
 * Como funciona: lê a lightness OKLCH do accent (l, 0–1). Se l ≥ 0.62, o
 * destaque é claro → texto preto (L=0). Se l < 0.62, é escuro → texto branco
 * (L=1). chroma 0 deixa o texto neutro (contraste máximo, sem tingir).
 * O pivô 0.62 (não 0.5) alinha o ponto de virada OKLCH ao ponto real de
 * virada de contraste WCAG para cores saturadas — validado empiricamente no
 * browser contra a paleta atual (accent #B12B79 → texto branco, 6.02:1) e
 * cores futuras hipotéticas (≥4.5:1 / AA em todos os tons de marca). Se a
 * paleta mudar no Elementor, a regra se re-resolve sozinha — nada a editar.
 *
 * A expressão `clamp(0, (l - 0.62) * 1000 + 0.5, 1)` é um degrau: vale ~0
 * quando l < 0.62 e ~1 quando l ≥ 0.62. `1 - degrau` inverte para a cor do
 * texto. Suporte: OKLCH relative color (Chrome 111+, Firefox 113+, Safari
 * 15.4+) — sem fallback necessário no parque de browsers atual.
 */
::selection {
    background-color: var(--e-global-color-accent);
    color           : oklch(from var(--e-global-color-accent) calc(1 - clamp(0, (l - 0.62) * 1000 + 0.5, 1)) 0 h);
}

::-moz-selection {
    background-color: var(--e-global-color-accent);
    color           : oklch(from var(--e-global-color-accent) calc(1 - clamp(0, (l - 0.62) * 1000 + 0.5, 1)) 0 h);
}

/* --- 2.5 Outline --- */
* {
    outline-color: var(--e-global-color-accent);
}

/* --- 2.6 Scrollbar --- */
::-webkit-scrollbar {
    width : 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--e-global-color-e03d05f, #DEDDD1);
}

::-webkit-scrollbar-thumb {
    background   : var(--e-global-color-bbe749d, #C02975);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: color-mix(in lab, var(--e-global-color-bbe749d, #C02975) 75%, black 25%);
}


/* ==========================================================================
   3. COMPONENTES
   ========================================================================== */

/* --- 3.1 Labels --- */
html body.elementor-kit-2553 label {
    color: var(--ucpa-color-main, #000);
}

/* --- 3.2 Accordion JetTabs (Exposições Anteriores / Galeria) ---
 * O plugin JetTabs aplica `border-radius: 5px` em `.jet-toggle`
 * (jet-tabs-frontend.css). Como cada item só tem `border-bottom`,
 * o raio curva as pontas da linha divisória (efeito gancho).
 * Zeramos o raio para manter as divisórias 100% retas.
 */
.jet-accordion .jet-toggle,
.jet-toggle.jet-accordion__item {
    border-radius: 0;
}

input.function:
async () => {
  await document.fonts.ready;
  const ps = [...document.querySelectorAll('.elementor-widget-text-editor p, .elementor-element p')];
  const targets = ['Nova publicação','Publicação também alerta'];
  const out = [];
  for (const t of targets) {
    const p = ps.find(el=>el.textContent.trim().startsWith(t));
    if(!p){ out.push({t,found:false}); continue; }
    const em = p.querySelector('em') || p;
    const cs = getComputedStyle(em);

    // Mede inclinação física do glifo renderizado (via clone medido em canvas
    // com a fonte computada do <em>)
    const W=320,H=200,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');
    x.clearRect(0,0,W,H);x.fillStyle='#000';x.textBaseline='alphabetic';
    x.font=`${cs.fontStyle} ${cs.fontWeight} 130px ${cs.fontFamily}`;
    x.fillText('N',70,165);
    const d=x.getImageData(0,0,W,H).data;
    const fi=(y)=>{for(let xx=0;xx<W;xx++){if(d[(y*W+xx)*4+3]>40)return xx;}return null;};
    let ys=[];for(let y=40;y<180;y++){if(fi(y)!=null)ys.push(y);}
    let angle=null;
    if(ys.length>=8){ const tp=ys[2],bt=ys[ys.length-3]; angle=+(Math.atan2(fi(tp)-fi(bt), bt-tp)*180/Math.PI).toFixed(1); }

    out.push({
      t, found:true,
      fontStyle: cs.fontStyle,
      fontFamily: cs.fontFamily.split(',')[0].replace(/["']/g,''),
      fontSynthesisStyle: cs.fontSynthesisStyle,
      fontSynthesisWeight: cs.fontSynthesisWeight,
      inclinacao_graus: angle,
      inclina: angle!=null && angle>6,
    });
  }
  return out;
}

